query MexFetchAllNewslettersMetadataJobQuery($fetch_status_metadata, $fetch_wamo_sub) {
  id
  type
  text
  update_time
  direct_path
  value
  xwa2_newsletter_subscribed {
    state {
      thread_metadata {
        creation_time
        name {
          picture {
            picture {
              description {
                invite
                handle
                verification
                settings {
                  reaction_codes {
                    wamo_sub {
                      plan_id
                      viewer_metadata {
                        settings {
                          role
                          wamo_sub_status
                          status_metadata {
                            last_status_server_id
                            last_status_sent_time
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
